-- v2 design-only additive schema, not applied to user data. Existing OpenCode session DB remains its own authority.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS hc_schema_versions(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hc_goals(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, user_objective TEXT NOT NULL, criterion_json TEXT NOT NULL, approved_revision INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','approved','active','paused','blocked','verified','canceled')), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS hc_runs(id TEXT PRIMARY KEY, goal_id TEXT NOT NULL REFERENCES hc_goals(id), status TEXT NOT NULL, epoch INTEGER NOT NULL DEFAULT 1, integrated_revision TEXT, chosen_model_json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS hc_tasks(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES hc_runs(id), task_key TEXT NOT NULL, deps_json TEXT NOT NULL, criteria_json TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(run_id,task_key));
CREATE TABLE IF NOT EXISTS hc_attempts(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES hc_tasks(id), ordinal INTEGER NOT NULL, selected_model_json TEXT NOT NULL, status TEXT NOT NULL, UNIQUE(task_id,ordinal));
CREATE TABLE IF NOT EXISTS hc_session_links(id TEXT PRIMARY KEY, run_id TEXT REFERENCES hc_runs(id), attempt_id TEXT REFERENCES hc_attempts(id), opencode_session_id TEXT NOT NULL, opencode_message_id TEXT, provider_revision TEXT, UNIQUE(attempt_id,opencode_session_id));
CREATE TABLE IF NOT EXISTS hc_executions(id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES hc_attempts(id), worker_id TEXT NOT NULL, fence INTEGER NOT NULL, status TEXT NOT NULL, last_heartbeat_ns INTEGER, UNIQUE(attempt_id,fence));
CREATE TABLE IF NOT EXISTS hc_effects(id TEXT PRIMARY KEY, execution_id TEXT NOT NULL REFERENCES hc_executions(id), intent_hash TEXT NOT NULL, idempotency_key TEXT NOT NULL, target_hash TEXT, effect_state TEXT NOT NULL CHECK(effect_state IN ('requested','started','applied','rejected','uncertain','compensated')), result_hash TEXT, UNIQUE(execution_id,idempotency_key));
CREATE TABLE IF NOT EXISTS hc_evidence(id TEXT PRIMARY KEY, task_id TEXT REFERENCES hc_tasks(id), criterion_id TEXT NOT NULL, revision_hash TEXT NOT NULL, environment_hash TEXT NOT NULL, verdict TEXT NOT NULL CHECK(verdict IN ('pass','fail','inconclusive')), artifact_hash TEXT, recorded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hc_worktree_pool(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, checkout_path TEXT NOT NULL UNIQUE, base_revision TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('provisioning','warm_idle','leased','dirty','quarantined','reaping','removed')), generation INTEGER NOT NULL DEFAULT 0, lease_id TEXT, pin_user_changes INTEGER NOT NULL DEFAULT 0 CHECK(pin_user_changes IN (0,1)), last_clean_hash TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hc_resource_leases(id TEXT PRIMARY KEY, execution_id TEXT REFERENCES hc_executions(id), resource_kind TEXT NOT NULL, resource_value TEXT NOT NULL, fence INTEGER NOT NULL, expires_mono_ns INTEGER NOT NULL, state TEXT NOT NULL, UNIQUE(resource_kind,resource_value,state));
CREATE TABLE IF NOT EXISTS hc_provider_health(id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, model_id TEXT NOT NULL, endpoint_hash TEXT NOT NULL, circuit_state TEXT NOT NULL CHECK(circuit_state IN ('closed','open','half_open')), ewma_latency_ms REAL, ewma_error_rate REAL, consecutive_failures INTEGER NOT NULL DEFAULT 0, next_probe_at TEXT, UNIQUE(provider_id,model_id,endpoint_hash));
CREATE TABLE IF NOT EXISTS hc_repair_patterns(id TEXT PRIMARY KEY, scoped_project_id TEXT, failure_fingerprint TEXT NOT NULL, strategy_json TEXT NOT NULL, quality_score REAL NOT NULL DEFAULT 0, last_observed TEXT, source_evidence_id TEXT, status TEXT NOT NULL CHECK(status IN ('proposed','validating','accepted','rejected','expired')), FOREIGN KEY(source_evidence_id) REFERENCES hc_evidence(id));
CREATE TABLE IF NOT EXISTS hc_idempotency_receipts(id TEXT PRIMARY KEY, actor TEXT NOT NULL, operation TEXT NOT NULL, target TEXT NOT NULL, request_hash TEXT NOT NULL, response_json TEXT NOT NULL, UNIQUE(actor,operation,target,id));
CREATE TABLE IF NOT EXISTS hc_event_outbox(id TEXT PRIMARY KEY, aggregate_id TEXT NOT NULL, source_event_id TEXT NOT NULL UNIQUE, event_type TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','sent','failed')), attempt_count INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_hc_tasks_ready ON hc_tasks(run_id,status);
CREATE INDEX IF NOT EXISTS idx_hc_effects_unsettled ON hc_effects(effect_state);
CREATE INDEX IF NOT EXISTS idx_hc_evidence_criterion ON hc_evidence(criterion_id,revision_hash);
CREATE INDEX IF NOT EXISTS idx_hc_pool_state ON hc_worktree_pool(project_id,state);
CREATE INDEX IF NOT EXISTS idx_hc_outbox_pending ON hc_event_outbox(status,id);
